ALTER TABLE public.posts ADD COLUMN IF NOT EXISTS vehicle_photo_path text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.vehicle_post_photo_allowed(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (split_part(_path,'/',1)=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.posts p WHERE p.vehicle_photo_path=_path AND p.module='vehicle' AND p.show_contact AND public.post_listing_visible(p) AND public.account_allowed(p.user_id) AND public.vehicle_contact_access(auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.vehicle_post_photo_allowed(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.vehicle_post_photo_allowed(text) TO authenticated,service_role;
CREATE POLICY vehicle_post_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='vehicle-post-photos' AND public.vehicle_post_photo_allowed(name));
CREATE POLICY vehicle_post_photo_private_boundary ON storage.objects AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(bucket_id<>'vehicle-post-photos' OR (auth.uid() IS NOT NULL AND public.vehicle_post_photo_allowed(name)));
CREATE POLICY vehicle_post_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='vehicle-post-photos' AND split_part(name,'/',1)=auth.uid()::text AND public.account_allowed(auth.uid()));
CREATE POLICY vehicle_post_photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='vehicle-post-photos' AND (split_part(name,'/',1)=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE OR REPLACE FUNCTION public.guard_vehicle_post_photo() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.vehicle_photo_path<>'' AND (NEW.module<>'vehicle' OR split_part(NEW.vehicle_photo_path,'/',1)<>NEW.user_id::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='vehicle-post-photos' AND name=NEW.vehicle_photo_path)) THEN RAISE EXCEPTION 'INVALID_POST_PHOTO'; END IF; RETURN NEW; END $$;
CREATE TRIGGER vehicle_post_photo_path_guard BEFORE INSERT OR UPDATE OF vehicle_photo_path ON public.posts FOR EACH ROW EXECUTE FUNCTION public.guard_vehicle_post_photo();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.get_post_details(uuid)'::regprocedure) INTO def; def:=replace(def,'''description'',p.description','''description'',CASE WHEN p.module<>''vehicle'' OR contact THEN p.description ELSE NULL END'); def:=replace(def,'''created_at'',p.created_at','''created_at'',p.created_at,''vehicle_photo_path'',CASE WHEN contact THEN p.vehicle_photo_path ELSE '''' END'); EXECUTE def; END $$;